import { t } from '../core/localizer';
import { icon } from './intro/helper';
import { uiModal } from './modal';
import { uiRapidSplash } from './rapid_splash';
export function uiRapidFirstEditDialog(context) {
  return function (selection) {
    var modalSelection = uiModal(selection);
    modalSelection.select('.modal').attr('class', 'modal rapid-modal'); // RapiD styling

    var firstEditModal = modalSelection.select('.content');
    firstEditModal.append('div').attr('class', 'modal-section').append('h3').html(t('rapid_first_edit.nice', {
      rapidicon: icon('#iD-logo-rapid', 'logo-rapid')
    }));
    firstEditModal.append('div').attr('class', 'modal-section').append('p').text(t('rapid_first_edit.text'));
    var buttonWrap = firstEditModal.append('div').attr('class', 'modal-actions');
    var exploring = buttonWrap.append('button').attr('class', 'rapid-explore').on('click', function () {
      modalSelection.close();
    });
    exploring.append('div').text(t('rapid_first_edit.exploring'));
    var loginToOsm = buttonWrap.append('button').attr('class', 'rapid-login-to-osm').on('click', function () {
      modalSelection.close();
      var osm = context.connection();
      if (!osm) return;
      osm.authenticate(function () {
        return context.container().call(uiRapidSplash(context));
      });
    });
    loginToOsm.append('div').text(t('rapid_first_edit.login_with_osm'));
    modalSelection.select('button.close').attr('class', 'hide');
  };
}